mapper.select:
select * from orders

    and number like concat('%', #{number}, '%') escape '!'
    and phone like concat('%', #{phone}, '%') escape '!'
    and status = #{status}
    and order_time >= #{beginTime}
    and order_time <= #{endTime}

order by order_time desc, id desc

mapper.update:
update orders set status = #{toStatus}
, delivery_time = #{deliveryTime}
where id = #{id} and status = #{fromStatus} and pay_status = 1

mapper.select:
select * from orders where user_id = #{userId}
and status = #{status}
order by order_time desc, id desc
